declare_tool_lint ! { #[doc = " The `implicit_sysroot_crate_import` detects use of `extern crate` to import non-sysroot crates"] #[doc = " (e.g. crates.io deps) from the sysroot, which is dangerous because these crates are not guaranteed"] #[doc = " to exist exactly once, and so may be missing entirely or appear multiple times resulting in ambiguity."] pub rustc :: IMPLICIT_SYSROOT_CRATE_IMPORT , Allow , "Forbid uses of non-sysroot crates in `extern crate`" , report_in_external_macro : true }